INSERT INTO ararka.tests (subject_id, grade, test_type, year, total_points, answer_key, scoring_notes, source_file_id)
VALUES ('algebra', 9, 'diagnostic', '2025', 15.0, '[{"number": 1, "points": 0.5, "type": "computation", "answer": "3x+2y-1=0: (1,-1) is solution (3-2-1=0), (3,0) is not (9+0-1=8≠0)", "scoring_notes": "Each correct check 0.25"}, {"number": 2, "points": 0.5, "type": "short_answer", "answer": "ays: x<2, բ: x<-2 (inequality solutions)", "scoring_notes": "Each correct solution 0.25"}, {"number": 3, "points": 1, "type": "fill_blank", "answer": "ays: a^m * a^n = a^(m+n), բ: (a^m)^n = a^(mn), գ: (ab)^m = a^m * b^m, դ: (a/b)^m = a^m/b^m", "scoring_notes": "Each correct rule 0.25"}, {"number": 4, "points": 1, "type": "short_answer", "answer": "ays: y=x^2 is increasing - FALSE, բ: sqrt(a^2)=|a| - TRUE, գ: sqrt(a+b)=sqrt(a)+sqrt(b) - FALSE, դ: sqrt(-a) has no meaning for any a - FALSE", "scoring_notes": "Each correct answer 0.25"}, {"number": 5, "points": 1, "type": "fill_blank", "answer": "-25 <= t <= 12 (temperature range)", "scoring_notes": "Correct double inequality 1.0"}, {"number": 6, "points": 1, "type": "table", "answer": "Rational expression values: x=2: (x-3)/(x+2)=-1/4, (2x-3)/x=1/2; x=0: (x-3)/(x+2)=-3/2, (2x-3)/x=undefined", "scoring_notes": "Each correct value 0.25"}, {"number": 7, "points": 1, "type": "short_answer", "answer": "Quadratic function has no zeros because graph doesn''t intersect x-axis", "scoring_notes": "Correct graphical interpretation 1.0"}, {"number": 8, "points": 0.5, "type": "computation", "answer": "x^2 - (5/2)x + 1 = 0 => 2x^2 - 5x + 2 = 0, D=25-16=9, x1=2, x2=1/2", "scoring_notes": "Correct clearing of fractions and discriminant 0.5, both roots 0.5"}, {"number": 9, "points": 0.5, "type": "computation", "answer": "sqrt(3)(sqrt(3)-sqrt(12))+sqrt(15) = 3-sqrt(6)+sqrt(15) = sqrt(12) [=sqrt(12)]", "scoring_notes": "Correct expansion 0.25, correct simplification 0.25"}, {"number": 10, "points": 1, "type": "computation", "answer": "System: subtract equations => y=4, substitute => x=-5. Solution: (-5, 4)", "scoring_notes": "Found one variable 0.5, found second by substitution 0.5"}, {"number": 11, "points": 1, "type": "computation", "answer": "(2x-3)-(x+4)+14>3x-6 => x<13/2, interval (-∞, 13/2)", "scoring_notes": "Correct expansion and simplification 0.5, correct solution and graph 0.5"}, {"number": 12, "points": 1, "type": "computation", "answer": "3/(sqrt(5)-4) * (sqrt(5)+4)/(sqrt(5)+4) = 3(sqrt(5)+4)/(5-16) = -3(sqrt(5)+4)/11", "scoring_notes": "Found conjugate 0.5, correct calculation 0.5"}, {"number": 13, "points": 1.5, "type": "computation", "answer": "Shopping problem: 50x + 10(16-x) = 400 => 40x=240 => x=6. Answer: 6 fifty-dram coins, 10 ten-dram coins", "scoring_notes": "Set up variable and relations 0.5, formed equation 0.5, solved correctly 0.5"}, {"number": 14, "points": 1.5, "type": "computation", "answer": "3x^2+3x-1=0. By Vieta: x1*x2=-1/3, x1+x2=-1. x1^2+x2^2=(x1+x2)^2-2*x1*x2=1+2/3=5/3", "scoring_notes": "Applied Vieta correctly 0.5, correct transformations 0.5, correct value 0.5"}, {"number": 15, "points": 2, "type": "essay", "answer": "System of equations has no solution because graphs are parallel lines (no intersection point)", "scoring_notes": "Correctly constructed both graphs 1.0, justified from graph positions 1.0"}]'::jsonb, NULL, '1zkqDpw89inqeqYM9zDIpfrzkfgCrJnXTrw0CTs6eJYw')
