VALUES ('algebra', 11, 'diagnostic_target', '2025', 15.0, '[{"number": 1, "points": 0.5, "type": "computation", "answer": "ays: 60° = π/3 radians, բ: 90° = π/2 radians", "scoring_notes": "Each correct conversion 0.25"}, {"number": 2, "points": 0.5, "type": "short_answer", "answer": "Shift f(x) graph 6 units up along y-axis", "scoring_notes": "Correct transformation description 0.5"}, {"number": 3, "points": 1, "type": "computation", "answer": "x = π/2 + πk", "scoring_notes": "Correct general solution 1.0"}, {"number": 4, "points": 1, "type": "multiple_choice", "answer": "գ: N ⊂ R (natural numbers are subset of reals)", "scoring_notes": "Correct selection 1.0"}, {"number": 5, "points": 1, "type": "fill_blank", "answer": "ays: (ab)^m = a^m * b^m, բ: (a^m)^n = a^(mn)", "scoring_notes": "Each correct rule 0.5"}, {"number": 6, "points": 1, "type": "fill_blank", "answer": "ays: y=cos(x) period 2π, բ: y=sin(x) period 2π, գ: y=tan(x) period π, դ: y=cot(x) period π", "scoring_notes": "Each correct period 0.25"}, {"number": 7, "points": 1, "type": "diagram", "answer": "Graph construction with axis intercepts", "scoring_notes": "Graph outline 0.5, intercept coordinates 0.5"}, {"number": 8, "points": 0.5, "type": "computation", "answer": "(5^(1/3))^3 = 5^(3/2)", "scoring_notes": "Correct calculation 0.5"}, {"number": 9, "points": 0.5, "type": "table", "answer": "Trig values at standard angles (same as base level)", "scoring_notes": "Correctly filled table 0.5"}, {"number": 10, "points": 1, "type": "computation", "answer": "y = 5 + sqrt(3x-2). D: x>=2/3. E: y>=5", "scoring_notes": "Correct domain 0.5, correct range 0.5"}, {"number": 11, "points": 1, "type": "computation", "answer": "n = 2 (since 2 < √7 < 3)", "scoring_notes": "Correct answer 1.0"}, {"number": 12, "points": 1, "type": "essay", "answer": "Even function proof for y=sin(x^2-1)+5x^4. y(-x)=sin((-x)^2-1)+5(-x)^4=sin(x^2-1)+5x^4=y(x)", "scoring_notes": "Correct proof 1.0"}, {"number": 13, "points": 1.5, "type": "computation", "answer": "Find cos(α) given sin(α)=0.6 and tan(α)>0. Since tan>0 and sin>0, cos>0. cos=sqrt(1-0.36)=0.8", "scoring_notes": "Correct value 1.0, correct sign determination 0.5"}, {"number": 14, "points": 1.5, "type": "computation", "answer": "(0.1)^(2-x) * 10^x = 10^(x-2) * 10^x = 10^(2x) * 10^(-2) = 0.01 * 100^x", "scoring_notes": "Convert to same base 0.5, separate known/unknown exponents 0.5, final form 0.5"}, {"number": 15, "points": 2, "type": "essay", "answer": "Prove 8cos10°cos20°cos40° = cot10°. Multiply and divide by sin10°, use double angle repeatedly: 2sin10°cos10°=sin20°, 2sin20°cos20°=sin40°, 2sin40°cos40°=sin80°. sin80°=cos10°. Result: cos10°/sin10°=cot10°", "scoring_notes": "Found multiplier (sin10°) 0.5, each correct double-angle step 0.5"}]'::jsonb, NULL, '1zkqDpw89inqeqYM9zDIpfrzkfgCrJnXTrw0CTs6eJYw')
